function OverseaManageLoungeControllerNode:Awake()
    local Bind = Bind
    self._listenerConf = {
        --[MaidCoffeeConstants.EventNames.UpdateLoungeSceneShowState] = Bind(self, self.OnEventShowLoungeScene),
        [MaidCoffeeConstants.EventNames.LoungeCatLoader]            = Bind(self, self.HandlerCats),
