function OverseaManageLoungeControllerNode:ShowLoungeScene()
    self._showSceneCo = CoStart(function() 
        self:ShowLoungeScene_()
        self._showSceneCo = nil
    end)
end
function OverseaManageLoungeControllerNode:StopShowSceneCo()
    if isNull(self._showSceneCo) then return end
    CoStop(self._showSceneCo)
    self._showSceneCo = nil
end

function OverseaManageLoungeControllerNode:ShowLoungeScene_()
    -- if self._isLoading then
