    -- end
    local dataProviderIns = self:GetDataProviderIns()
    dataProviderIns:SetIsLoadSceneComplete(false)
    dataProviderIns:SetController(self)
    
    self:LoadScene_()
    
    dataProviderIns:SetIsLoadSceneComplete(true)
