function OverseaManageLoungeControllerNode:LoadScene_()
    local go = GameUtils.LoadBundleAsync("Prefabs/Runtime/MaidCoffee_Lounge.prefab", nil, false)
    Events.Broadcast(Constants.EventNames.UIMainHomeSceneFocusShowEventName, false)
    
    local locNode        = GameUtils.LoadBundleAsync(MaidCoffeeConstants.PrefabPath.CatRoom_loc, go)
    local loungeCapacity = checkNumber(MaidCoffeeUtils.GetMaidCoffeeManagerSettingVo(MaidCoffeeConstants.ParamsIds.LoungeCapacity).num)
    local transform      = locNode.transform
    for i = 1, loungeCapacity do
        local node = transform:Find(string.format("loc%s", i))
        if not isNull(node) then
            self._locationNodes[i] = node.gameObject
        end
    end
    
    local camLoc = transform:Find("cam_loc1")
    DataProvider:GetInstance():SetCatLocationNodes(self._locationNodes)
    DataProvider:GetInstance():SetCamLoc(camLoc)
    
    self._sceneIns = go

    local cameraTransform = go.transform:Find("Main Camera")
    self._cameraTransform = cameraTransform
    -- KTool.GetOrAddComponent(cameraTransform, )
    if not isNull(cameraTransform) then
        DataProvider:GetInstance():SetCamOriginLoc(cameraTransform)

    end
    
end

function OverseaManageLoungeControllerNode:HandlerCats(cardSkins)
    local conditionKey = "OverseaManageLoungeControllerNode:LoadCats"
    
    CfUtils.ConditionAppend(conditionKey)
    cs_coroutine.start(function()
        xTry(function()
            --local index2Loaders
            for index, cardSkin in ipairs(cardSkins) do
                ---@type CatTouchController
                local touchController = self._index2CatController[index]
                if touchController == nil then
                    touchController = CatTouchController.New()
                    self._index2CatController[index] = touchController
                end
                local locationNode = self._locationNodes[index]
                touchController:Init(cardSkin, locationNode, CardProgressionConstants.CatTouchIdleFlag.Sleep)
            end

            for i, controller in pairs(self._index2CatController) do
                while not controller:CheckIsLoadComplete() do
                    cs_coroutine.yield_return()
                end
            end
            
            CfUtils.ConditionRemove(conditionKey)
        end, function()

            CfUtils.ConditionRemove(conditionKey)
        end)
    end)
end

---ClearCats
---通过清理所有猫
function OverseaManageLoungeControllerNode:ClearCats(isDestroy)
    ---@param controller CatTouchController
    for i, controller in pairs(self._index2CatController) do
        controller:Release()
    end
    if isDestroy then
        self._index2CatController = nil
    end

end

