---通过下标清理猫
function OverseaManageLoungeControllerNode:ClearCatByIndex(index)
    ---@type CatTouchController
    local controller = self._index2CatController[index]
    controller:Release()
    
end

---HandlerFocusCat
---处理 聚集于猫
---@param index number 猫在孵化池的下标
function OverseaManageLoungeControllerNode:HandlerFocusCat(index)
    local locationNode   = self._locationNodes[index]

    ---@param controller CatTouchController
    for index_, controller in pairs(self._index2CatController) do
        if index_ == index then
            controller:Focus(locationNode.transform)
        else
            controller:UpdateCatShowState(false)
        end
    end

    ---@type CatTouchController
    local controller     = self._index2CatController[index]
    controller:Focus(locationNode.transform)
    
    --local transform      = locationNode.transform
    --local forward        = transform.forward
    --local up             = transform.up
    --local cameraPosition = transform.position + forward * 1.5 + up * 0.1
    --local cameraTransform = URPCameraController.Instance.mainCamera.transform
    --cameraTransform.position = cameraPosition
    --cameraTransform.rotation = Quaternion.unity_quaternion.LookRotation(forward * -1)
    
    ---进入待机循环
    self:HandlerPlayCatAni(index, CardProgressionConstants.CatTouchFlag.IdleQuit, CardProgressionConstants.CatTouchIdleFlag.Default)
end

---HandlerShowAllCat
---处理显示所有猫
function OverseaManageLoungeControllerNode:HandlerShowAllCat(isSleep)
    ---@param controller CatTouchController
    for index_, controller in pairs(self._index2CatController) do
        controller:UpdateCatShowState(true)
        if isSleep then
            controller:EnterSleep()
        end
    end
end

---HandlerPlayCatAni
---处理播放猫动画
function OverseaManageLoungeControllerNode:HandlerPlayCatAni(cardIndex, touchFlag, idleFlag)
    ---@type CatTouchController
    local controller     = self._index2CatController[cardIndex]
    controller:HandlerPlayCatAni(touchFlag, idleFlag)
end

